"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["29725"],{11642(e){e.exports=JSON.parse('{"id":"V4-033","slug":"tax-free-savings-account","term":"Tax-Free Savings Account (TFSA)","also_known_as":[],"difficulty":"Intermediate","definition":"A Tax-Free Savings Account (TFSA) is a savings and investment account in Canada in which investment income and gains are tax-free, and withdrawals can be made at any time without tax.","explanation":["TFSAs were introduced in Canada in 2009. Contributions are made from income that has already been taxed and are not deductible, but everything earned inside the account, including interest, dividends and capital gains, is free of tax.","Each Canadian resident aged 18 or over accumulates contribution room every year, set by the government, and unused room carries forward. Amounts withdrawn are added back to contribution room from the following calendar year, which gives TFSAs considerable flexibility.","For example, someone who invests in a TFSA for many years can withdraw the money, including all the growth, tax-free to buy a car, fund a business or supplement retirement income.","TFSAs can hold cash, guaranteed investment certificates, funds, shares and bonds. Despite the name, they are not just for cash savings. Over-contributing results in a penalty tax. TFSAs are similar to ISAs in the United Kingdom and Roth IRAs in the United States, and are often used alongside Registered Retirement Savings Plans."],"note":"","total":1725,"prev":{"slug":"tax-free-growth","term":"Tax-Free Growth"},"next":{"slug":"tax-haven","term":"Tax Haven"}}')}}]);